class pool {
  std::vector<std::jthread> workers_;
  std::mutex m_; std::condition_variable cv_; std::queue<Task> q_;
public:
  explicit pool(unsigned n) { for (unsigned i = 0; i < n; ++i)
      workers_.emplace_back([this](std::stop_token st) { loop(st); }); }
